  (id, question_id, version, state, text, explanation, category_id, country_scope, difficulty, age_rating, tags, language, sources, content_hash, published_at)
values
  ('f5cd906a-a810-5a9b-896f-42d20a30c772', '9d2721fa-2faa-5792-b172-2fe8bba9f486', 1, 'approved', 'The Cradle of Humankind, a World Heritage Site rich in early human fossils, is in which country?', 'The Cradle of Humankind, near Johannesburg, includes the Sterkfontein caves, where “Mrs Ples” and “Little Foot” were found.', 'science', array['ZA']::text[], 'hard', 'all', array['starter-set', 'needs-review']::text[], 'en', '[{"title":"Wikipedia: Cradle of Humankind","url":"https://en.wikipedia.org/wiki/Cradle_of_Humankind"}]'::jsonb, '3ec6b3281824a278d8b79b8fff89c018d50ad8eefa7fe84931ddd5be9c6af735', now()),
  ('ae5ffea0-11a7-564b-ba2f-70b4812525ea', '1e320593-03a6-5a9a-879d-ba1f0c5438f9', 1, 'approved', 'The okapi, a forest relative of the giraffe, lives in the wild only in which country?', 'The okapi is endemic to the rainforests of DR Congo, where it is a national symbol.', 'science', array['CD']::text[], 'hard', 'all', array['starter-set', 'needs-review']::text[], 'en', '[{"title":"Wikipedia: Okapi","url":"https://en.wikipedia.org/wiki/Okapi"}]'::jsonb, 'd156f9a4cbc57c84d8845e5de49a9487161229f4022ee656deab4e83b22d6690', now()),
  ('63cbb03b-2053-51a8-8352-7fc538f515e3', 'deaaa653-da53-5db6-af46-c749cf0c7e74', 1, 'approved', 'The Square Kilometre Array radio telescope is being built in Australia and which African country?', 'The SKA’s mid-frequency dishes are being built in South Africa’s Karoo, building on the MeerKAT telescope.', 'science', array['ZA']::text[], 'hard', 'all', array['starter-set', 'needs-review']::text[], 'en', '[{"title":"Wikipedia: Square Kilometre Array","url":"https://en.wikipedia.org/wiki/Square_Kilometre_Array"}]'::jsonb, 'ce431ac613331f09c77d918857db417eecfa35453b4ab024d3d6ad59cb88c7f3', now()),
  ('24e8830a-e191-5716-838a-6a30a3028a6a', '49659659-1c40-5bcd-a74e-7e0f2d52dccf', 1, 'approved', 'M-Pesa, the mobile money service launched in 2007, started in which country?', 'Safaricom launched M-Pesa in Kenya in 2007, letting people send and receive money by phone.', 'innovation', array['KE']::text[], 'easy', 'all', array['starter-set', 'needs-review']::text[], 'en', '[{"title":"Wikipedia: M-Pesa","url":"https://en.wikipedia.org/wiki/M-Pesa"}]'::jsonb, 'befcab574ca89530757102f33b6d919a89ac607546cd4c18b924e106fcbc35ac', now()),
  ('6979a914-4ad2-50a9-8e9e-5e99e68f426b', '4f1d7e9a-5f56-56ea-b9e4-6d709ee6c79b', 1, 'approved', 'Which South African-born entrepreneur founded SpaceX?', 'Elon Musk was born in Pretoria in 1971 and founded SpaceX in 2002.', 'innovation', array['ZA']::text[], 'easy', 'all', array['starter-set', 'needs-review']::text[], 'en', '[{"title":"Wikipedia: Elon Musk","url":"https://en.wikipedia.org/wiki/Elon_Musk"}]'::jsonb, '21c3f8aa4a6e004a241937984c9298f05cec5d332c49524e87d9a1203a00bdd6', now()),
  ('92c1b948-14dd-50a1-8b5e-1d0e8f1e8053', '76dd32ab-09a6-5b93-a9e0-8482d2f789c4', 1, 'approved', 'Which country’s tech scene is nicknamed “Silicon Savannah”?', '“Silicon Savannah” refers to Kenya’s tech sector, centred on Nairobi.', 'innovation', array['KE']::text[], 'easy', 'all', array['starter-set', 'needs-review']::text[], 'en', '[{"title":"Wikipedia: Silicon Savannah","url":"https://en.wikipedia.org/wiki/Silicon_Savannah"}]'::jsonb, '48c67307528d3f4e916139248489ab5e47453e29ce1d3bf9d1739c5dc8a345fd', now()),
  ('bfa216b1-3b1e-5942-9006-0fd5a4c0768d', '4c58049e-48c0-5fc5-bb65-0a7df5c7de0f', 1, 'approved', 'The online marketplace Jumia was founded in 2012 in which country?', 'Jumia launched in Lagos, Nigeria, in 2012 and expanded across Africa.', 'innovation', array['NG']::text[], 'medium', 'all', array['starter-set', 'needs-review']::text[], 'en', '[{"title":"Wikipedia: Jumia","url":"https://en.wikipedia.org/wiki/Jumia"}]'::jsonb, '663ece96e786cb18e6051068b16bab29ea822494af5ebc90bda163383e90061e', now()),
  ('849c6a7e-7cd9-57a1-9102-432c3821106a', 'd6e38241-cf49-513f-989e-2d81496c0097', 1, 'approved', 'Which Lagos-founded payments company was bought by Stripe in 2020?', 'Stripe acquired Paystack in 2020, one of the largest deals in African tech at the time.', 'innovation', array['NG']::text[], 'medium', 'all', array['starter-set', 'needs-review']::text[], 'en', '[{"title":"Wikipedia: Paystack","url":"https://en.wikipedia.org/wiki/Paystack"}]'::jsonb, '6a9c8f15b3a02122f81f7ba59c7610ce0b5fbc5b5922cbf94c618fef83254b19', now()),
  ('54f3189d-031d-5a89-ab7a-bff86fbf5bf2', 'a4f908be-9a9b-539b-9ebf-59552e86175c', 1, 'approved', 'The Grand Ethiopian Renaissance Dam is built on which river?', 'The dam on the Blue Nile in western Ethiopia is the largest hydroelectric plant in Africa.', 'innovation', array['ET']::text[], 'medium', 'all', array['starter-set', 'needs-review']::text[], 'en', '[{"title":"Wikipedia: Grand Ethiopian Renaissance Dam","url":"https://en.wikipedia.org/wiki/Grand_Ethiopian_Renaissance_Dam"}]'::jsonb, 'ba62e767c5f9adf45af7e09dae766a20d643de42562289edb622603031155bde', now()),
  ('6104fad1-798a-5353-802f-bd2046723530', 'e67f7323-59d3-512b-9ac4-78c921cf635f', 1, 'approved', 'Aliko Dangote, for many years Africa’s richest person, built his fortune mainly in which industry?', 'Dangote Cement is Africa’s largest cement producer. The Dangote Group has since built a major oil refinery near Lagos.', 'innovation', array['NG']::text[], 'medium', 'all', array['starter-set', 'needs-review']::text[], 'en', '[{"title":"Wikipedia: Aliko Dangote","url":"https://en.wikipedia.org/wiki/Aliko_Dangote"}]'::jsonb, '40dcab8ed33d9a9dfa8bf88cc9f606a15b0fa1265de1c7289fc4a82f94b3acd7', now()),
  ('35a81212-9cac-5e42-b7ea-27360edef073', 'e4ce384b-71f0-5e5c-80ce-3fa8299675cb', 1, 'approved', 'The Inga dams, at one of the world’s greatest potential hydropower sites, are in which country?', 'Inga I and Inga II stand on the lower Congo River in DR Congo, near the Inga Falls.', 'innovation', array['CD']::text[], 'hard', 'all', array['starter-set', 'needs-review']::text[], 'en', '[{"title":"Wikipedia: Inga dams","url":"https://en.wikipedia.org/wiki/Inga_dams"}]'::jsonb, 'a9c458ed2bfba85c4e34dc7e2e02ef33b64e11ffde998595c31011cd7660cdbc', now()),
  ('75a618cb-d46c-5492-9aac-cc1f8c772b48', '42073b1c-dc01-5109-82c0-c236e765eb1e', 1, 'approved', 'Which Sudanese-born telecoms entrepreneur founded Celtel and a prize for African leadership?', 'Mo Ibrahim founded Celtel in 1998 and set up the Mo Ibrahim Foundation, which awards the Ibrahim Prize.', 'innovation', array['SD']::text[], 'hard', 'all', array['starter-set', 'needs-review']::text[], 'en', '[{"title":"Wikipedia: Mo Ibrahim","url":"https://en.wikipedia.org/wiki/Mo_Ibrahim"}]'::jsonb, '7e4488f037e3d4c76fa66d82ea609f7d305ec482ef5499e21c17b918065ef5ab', now()),
  ('a617c991-7dfb-5fd1-a0a4-482f7e2534ac', 'e887705f-9101-5500-b26a-791d503c34aa', 1, 'approved', 'Strive Masiyiwa founded which telecoms group, which began in Zimbabwe?', 'Strive Masiyiwa founded Econet Wireless, which won a long legal battle to launch mobile service in Zimbabwe in the 1990s.', 'innovation', array['ZW']::text[], 'hard', 'all', array['starter-set', 'needs-review']::text[], 'en', '[{"title":"Wikipedia: Strive Masiyiwa","url":"https://en.wikipedia.org/wiki/Strive_Masiyiwa"}]'::jsonb, 'add45fa71fadc9d99adf42a9d80c87eaf06cfcb415b10cb8933ae52173d0abb5', now()),
  ('c2ddac65-7c24-59d5-ba46-65e5accf4913', '4bd0537b-ee7a-53b9-ab63-5d7634c0dd75', 1, 'approved', 'The Noor Ouarzazate complex, one of the world’s largest concentrated solar power plants, is in which country?', 'Noor Ouarzazate, on the edge of the Sahara in Morocco, uses mirrors to concentrate sunlight to generate electricity.', 'innovation', array['MA']::text[], 'hard', 'all', array['starter-set', 'needs-review']::text[], 'en', '[{"title":"Wikipedia: Ouarzazate Solar Power Station","url":"https://en.wikipedia.org/wiki/Ouarzazate_Solar_Power_Station"}]'::jsonb, '5f0861a1181f1639bc49fd7a3862d600087e4ab909b3d751c64a309cbca1b1ff', now()),
  ('31e8ceef-3001-5898-833c-8b51fa3977ef', '43808bae-0970-5b62-a092-f4bdbe943b63', 1, 'approved', 'What is the currency of Nigeria?', 'The naira, introduced in 1973, is Nigeria’s currency.', 'society', array['NG']::text[], 'easy', 'all', array['starter-set', 'needs-review']::text[], 'en', '[{"title":"Wikipedia: Nigerian naira","url":"https://en.wikipedia.org/wiki/Nigerian_naira"}]'::jsonb, 'a3d65c8f3d70ea348e92c988d66080b7170f0e190b81686ef784286fa77482a9', now()),
  ('75b87765-e3d4-56ca-8d52-7624efc7e4b1', '91579869-0959-5ecb-b419-7c535b7bf9be', 1, 'approved', 'What is the currency of South Africa?', 'The rand takes its name from the Witwatersrand, the ridge where Johannesburg’s gold was found.', 'society', array['ZA']::text[], 'easy', 'all', array['starter-set', 'needs-review']::text[], 'en', '[{"title":"Wikipedia: South African rand","url":"https://en.wikipedia.org/wiki/South_African_rand"}]'::jsonb, '6b6411b03fcae6cd65012470312e95346aa47ed670e9fe014c89d0cc963ce4e8', now()),
  ('7a810016-6201-5e25-ba2d-704dcd6f2aff', 'a8bda4cc-0bcf-5bfd-8866-92a900af3a13', 1, 'approved', 'Which African country has the largest population?', 'Nigeria is Africa’s most populous country, with over 200 million people.', 'society', array['NG']::text[], 'easy', 'all', array['starter-set', 'needs-review']::text[], 'en', '[{"title":"Wikipedia: Demographics of Nigeria","url":"https://en.wikipedia.org/wiki/Demographics_of_Nigeria"}]'::jsonb, '4653d4dfc63617176a64d8042495c9a73cef23e226bda4b85cb6576e528d9d6b', now()),
  ('88008af0-a95c-511f-90a8-984bd02f0d17', '3fb0029a-92e8-57dd-95ad-7a8fd77d558a', 1, 'approved', 'Ellen Johnson Sirleaf became Africa’s first elected female head of state in which country?', 'Ellen Johnson Sirleaf was President of Liberia from 2006 to 2018 and shared the 2011 Nobel Peace Prize.', 'society', array['LR']::text[], 'medium', 'all', array['starter-set', 'needs-review']::text[], 'en', '[{"title":"Wikipedia: Ellen Johnson Sirleaf","url":"https://en.wikipedia.org/wiki/Ellen_Johnson_Sirleaf"}]'::jsonb, 'd3c0d2f0ec95fd8fc90362dff91effadedcb97f671ebe5361035b51fcadef096', now()),
  ('15d288e8-5e73-5b5e-84a7-316cdb7140c9', 'c6df5383-fc52-5f9a-a43e-f970ba3d8b79', 1, 'approved', 'How many member states does the African Union have?', 'All 55 internationally recognised states of the continent, including the Sahrawi Republic, are AU members.', 'society', array['AFRICA']::text[], 'medium', 'all', array['starter-set', 'needs-review']::text[], 'en', '[{"title":"Wikipedia: Member states of the African Union","url":"https://en.wikipedia.org/wiki/Member_states_of_the_African_Union"}]'::jsonb, '13b9ecf833e8d0f8f8fca297904707fa92480b60944b573062a94a69e44f3590', now()),
  ('e1597daa-8045-52e1-ae53-612e392e55f1', '6bc372bc-1046-5445-8fa3-bec01eaf390d', 1, 'approved', 'Africa Day, marking the founding of the OAU, is celebrated on which date?', 'Africa Day is held every year on 25 May, the date the Organisation of African Unity was founded in 1963.', 'society', array['AFRICA']::text[], 'medium', 'all', array['starter-set', 'needs-review']::text[], 'en', '[{"title":"Wikipedia: Africa Day","url":"https://en.wikipedia.org/wiki/Africa_Day"}]'::jsonb, '0e7822d76a607c25ff1fa376ddd77bfe5e96253e0808836909f60a76654d6c1c', now()),
  ('104031a0-0750-5a70-9421-4be7481bbb3b', 'c1c353b3-a3c3-5cde-9317-935d9a88b86f', 1, 'approved', 'The cedi is the currency of which country?', 'The Ghanaian cedi takes its name from the Akan word for cowry shells, once used as money.', 'society', array['GH']::text[], 'medium', 'all', array['starter-set', 'needs-review']::text[], 'en', '[{"title":"Wikipedia: Ghanaian cedi","url":"https://en.wikipedia.org/wiki/Ghanaian_cedi"}]'::jsonb, '6f669be6a8f0117714968b056519044c74bc422f2e07350d16230e1ddf87db0c', now()),
  ('5499159c-f3c0-5d94-b5d5-bba97ba2c36b', '34c47f95-a71e-5336-a1b3-50f5e9bd49ef', 1, 'approved', 'The East African Community has its headquarters in which city?', 'The East African Community secretariat is in Arusha, Tanzania.', 'society', array['TZ', 'EAST']::text[], 'hard', 'all', array['starter-set', 'needs-review']::text[], 'en', '[{"title":"Wikipedia: East African Community","url":"https://en.wikipedia.org/wiki/East_African_Community"}]'::jsonb, '389fd99edced3e065b2119d9c7756006b26cc38a008da3c22890fa93988b504c', now()),
  ('52b8293c-dac8-5ec9-8f01-87924c866555', '36dffdd6-baa2-5093-9516-f977ce50a706', 1, 'approved', 'The secretariat of the African Continental Free Trade Area (AfCFTA) is in which city?', 'The AfCFTA secretariat opened in Accra, Ghana, in 2020.', 'society', array['GH', 'AFRICA']::text[], 'hard', 'all', array['starter-set', 'needs-review']::text[], 'en', '[{"title":"Wikipedia: African Continental Free Trade Area","url":"https://en.wikipedia.org/wiki/African_Continental_Free_Trade_Area"}]'::jsonb, 'b183a95b9d13d4afc1db246f18f3058fe4658ecbce7b4573e7835ac9306b9c72', now()),
  ('9c0401f8-e940-5d28-97de-2bdc047dde64', 'a22c1ae1-e9a8-5f64-8949-191b1781cf17', 1, 'approved', 'Which country’s parliament has had the world’s highest share of women members?', 'Women have held a majority of seats in Rwanda’s lower house since 2008, the highest share in the world.', 'society', array['RW']::text[], 'hard', 'all', array['starter-set', 'needs-review']::text[], 'en', '[{"title":"Wikipedia: Women in Rwanda","url":"https://en.wikipedia.org/wiki/Women_in_Rwanda"}]'::jsonb, 'cf23e53efbd9dd0d3576add8d0c73d040c5acdf478fdefade2e4577bed09714e', now()),
  ('fd59f7bf-a660-56cb-a86d-ec6bb7b17145', 'c96af456-6580-55c8-858b-52d2e595768d', 1, 'approved', 'In which South African town does the Pan-African Parliament meet?', 'The Pan-African Parliament, the African Union’s legislative body, sits in Midrand, Gauteng, South Africa.', 'society', array['ZA', 'AFRICA']::text[], 'hard', 'all', array['starter-set', 'needs-review']::text[], 'en', '[{"title":"Wikipedia: Pan-African Parliament","url":"https://en.wikipedia.org/wiki/Pan-African_Parliament"}]'::jsonb, '7120b9c1382f2daa9d8d9ec4d0100a5428f6569ca5929fb4e16db7374de6dede', now())
